// P12 로컬 골격: STORAGE-DESIGN 6.1 계약만 검사한다.
// 물리 저장소가 합의·연결되기 전에는 성공 StateRef를 만들거나 상태를 변경하지 않는다.
const input = $json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const isText = (v) => typeof v === 'string' && v.trim().length > 0;
const hasOwn = (v, key) => Object.prototype.hasOwnProperty.call(v, key);
const hasOnlyKeys = (v, allowed) => isObj(v) && Object.keys(v).every((key) => allowed.has(key));
const isNullableVersion = (v) => v === null;
const isStateRef = (v) => isObj(v) && isText(v.scope) && isText(v.request_id) && isText(v.owner_id) && isText(v.input_hash) && isText(v.execution_id) && Number.isInteger(v.state_revision) && v.state_revision >= 0;
const isSource = (v) => isObj(v) && isText(v.doc) && isText(v.section) && typeof v.score === 'number' && Number.isFinite(v.score);
const isFact = (v) => isObj(v) && isText(v.key) && typeof v.value === 'string' && ['user', 'document', 'api'].includes(v.origin) && (!hasOwn(v, 'reference') || typeof v.reference === 'string');
const isCaseFacts = (v) => isObj(v) && typeof v.summary === 'string' && Array.isArray(v.reported) && v.reported.every(isFact) && Array.isArray(v.confirmed) && v.confirmed.every(isFact) && Array.isArray(v.attempted_actions) && v.attempted_actions.every((item) => typeof item === 'string') && Array.isArray(v.missing) && v.missing.every((item) => typeof item === 'string') && Array.isArray(v.uncertainties) && v.uncertainties.every((item) => typeof item === 'string') && Array.isArray(v.evidence_refs) && v.evidence_refs.every(isSource);
const isOutcome = (v) => isObj(v) && ['guidance', 'ask', 'handoff', 'urgent', 'deny', 'failure'].includes(v.mode) && ['자동 답변', '보완 질문', '담당자 이관', '권한 없음', '차단'].includes(v.route) && typeof v.answer === 'string' && Array.isArray(v.sources) && v.sources.every(isSource) && typeof v.close_required === 'boolean' && isText(v.support_status) && (v.reason === null || typeof v.reason === 'string');
const isSecurity = (v) => isObj(v) && (v.blocked_by === null || typeof v.blocked_by === 'string') && (v.reason === null || typeof v.reason === 'string') && Number.isInteger(v.masked) && v.masked >= 0;
const isTicket = (v) => v === null || (isObj(v) && isText(v.ticket_id) && ['normal', 'high'].includes(v.priority) && typeof v.duplicate === 'boolean');
const isResponse = (v) => isObj(v) && isText(v.request_id) && ['자동 답변', '보완 질문', '담당자 이관', '권한 없음', '차단'].includes(v.route) && typeof v.answer === 'string' && Array.isArray(v.sources) && v.sources.every(isSource) && isTicket(v.ticket) && Array.isArray(v.agents) && v.agents.every(isText) && isSecurity(v.security);
const requestId = isObj(input) && isObj(input.state_ref) && isText(input.state_ref.request_id) ? input.state_ref.request_id : (isObj(input) && isObj(input.request) && isText(input.request.request_id) ? input.request.request_id : null);

if (!isObj(input) || !isText(input.op)) {
  return [{ json: { request_id: requestId, ok: false, skipped: false, state_ref: null, error_code: 'invalid_state_request' } }];
}

if (input.op === 'begin') {
  const valid = isText(input.scope) && isText(input.execution_id) && isText(input.input_hash) && isObj(input.actor) && isText(input.actor.id) && isObj(input.request) && isText(input.request.request_id);
  return [{ json: {
    request_id: requestId,
    mode: 'error',
    state_ref: null,
    support: null,
    facts: null,
    response: null,
    http_status: valid ? 503 : 400,
    error_code: valid ? 'state_backend_unconfigured' : 'invalid_state_request'
  } }];
}

if (input.op === 'save') {
  const valid = typeof input.deadline_at === 'string' && Number.isFinite(Date.parse(input.deadline_at)) && isStateRef(input.state_ref) && input.response?.request_id === input.state_ref.request_id && isText(input.case_id) && isText(input.first_request_id) && Number.isInteger(input.attempt) && input.attempt >= 1 && hasOwn(input, 'expected_case_version') && isNullableVersion(input.expected_case_version) && isText(input.ticket_id) && isCaseFacts(input.facts) && isOutcome(input.outcome) && isResponse(input.response);
  return [{ json: {
    request_id: requestId,
    ok: false,
    state_ref: null,
    error_code: valid ? 'state_backend_unconfigured' : 'invalid_state_request',
    recovery: { version: 1, mode: 'manual_required', action: 'finish', args: null, reference: null, reason: valid ? '물리 저장소 미연결' : '저장 요청 계약 오류' }
  } }];
}

const validatePrepare = (args) => hasOnlyKeys(args, new Set(['current_step'])) && isText(args.current_step);
const validateBind = (args) => {
  if (!hasOnlyKeys(args, new Set(['jira_issue_id', 'key', 'jira_issue_key', 'case_id', 'first_request_id', 'next_step']))) return false;
  const hasKey = hasOwn(args, 'key');
  const hasIssueKey = hasOwn(args, 'jira_issue_key');
  return isText(args.jira_issue_id) && hasKey !== hasIssueKey && isText(hasKey ? args.key : args.jira_issue_key) && isText(args.case_id) && isText(args.first_request_id) && isText(args.next_step);
};
const validateFinish = (args) => hasOnlyKeys(args, new Set(['response', 'current_step'])) && isResponse(args.response) && args.current_step === 'respond';
const validateFail = (args) => hasOnlyKeys(args, new Set(['status', 'current_step', 'error_code'])) && ['failed', 'unknown'].includes(args.status) && isText(args.current_step) && isText(args.error_code);
const validators = { prepare: validatePrepare, bind: validateBind, finish: validateFinish, fail: validateFail };
const noOwnedState = input.op === 'fail' && input.state_ref === null && isText(input.scope) && isText(input.execution_id);
if (noOwnedState && isObj(input.args) && validateFail(input.args)) {
  return [{ json: { request_id: requestId, ok: true, skipped: true, state_ref: null, error_code: null } }];
}
const validFailTarget = isStateRef(input.state_ref);
const validStateTarget = input.op === 'fail' ? validFailTarget : isStateRef(input.state_ref);
const valid = hasOwn(validators, input.op) && validStateTarget && isObj(input.args) && validators[input.op](input.args);
return [{ json: {
  request_id: requestId,
  ok: false,
  skipped: false,
  state_ref: null,
  error_code: valid ? 'state_backend_unconfigured' : 'invalid_state_request'
} }];

const original = $('S01 상태 명령 수신').first().json;
const raw = $json.result;
let result = raw;
if (typeof raw === 'string') { try { result = JSON.parse(raw); } catch { result = null; } }
if (!result || typeof result !== 'object' || Array.isArray(result)) {
  if (original.op === 'begin') return [{json:{request_id:original.request?.request_id ?? null,mode:'error',state_ref:null,support:null,facts:null,response:null,http_status:503,error_code:'state_error'}}];
  if (original.op === 'save') return [{json:{request_id:original.state_ref?.request_id ?? null,ok:false,state_ref:null,error_code:'state_error',recovery:{version:1,mode:'manual_required',action:'finish',args:null,reference:null,reason:'상태 저장 결과 확인 실패'}}}];
  return [{json:{request_id:original.state_ref?.request_id ?? null,ok:false,skipped:false,state_ref:null,error_code:'state_error'}}];
}
if (original.op === 'save' && !Object.prototype.hasOwnProperty.call(result, 'recovery')) result.recovery = {version:1,mode:'manual_required',action:'inspect_only',args:null,reference:null,reason:result.ok ? null : '상태 저장 미확인'};
// begin의 409 응답은 시민에게 그대로 전달되므로 코드별 확정 문구로 바꾼다. 접수·완료·자동 복구는 약속하지 않는다.
const BEGIN_MESSAGES = {
  request_in_progress: '같은 요청을 처리하고 있습니다. 같은 요청은 자동으로 다시 실행하지 않습니다.',
  request_requires_review: '처리 결과 확인이 필요하며, 같은 요청은 자동으로 다시 실행하지 않습니다.',
  request_conflict: '같은 요청 번호로 다른 내용이 들어왔습니다. 새 문의로 다시 보내 주세요.'
};
if (original.op === 'begin' && result.response && Array.isArray(result.response.codes)) {
  const known = result.response.codes.find((code) => Object.prototype.hasOwnProperty.call(BEGIN_MESSAGES, code));
  if (known) result.response = {...result.response, error: BEGIN_MESSAGES[known]};
}
return [{json:result}];

const input = $('S01 상태 명령 수신').first().json;
if(Date.parse(input.deadline_at)-Date.now()<1000)return [{json:{request_id:input.state_ref.request_id,ok:false,state_ref:input.state_ref,error_code:'state_error',recovery:{version:1,mode:'manual_required',action:'finish',args:null,reference:null,reason:'deadline_exceeded'}}}];
return [{json:{deadline_at:input.deadline_at,req:{path:'/rest/api/2/issue/'+encodeURIComponent(input.ticket_id)+'?fields=labels,status,description,assignee'}}}];

// BEGIN shared case-context library
// Canonical n8n Code library. build_case_context_nodes.py embeds this function
// into exported workflows; no runtime filesystem/require permission is needed.
function caseContextLibrary() {
  const MARKER = '[dubakwi-case-context:v1]';
  const object = v => !!v && typeof v === 'object' && !Array.isArray(v);
  const text = v => typeof v === 'string' && v.length > 0;
  const fail = code => { throw new Error(code); };
  const sorted = v => Array.isArray(v) ? v.map(sorted) : object(v)
    ? Object.fromEntries(Object.keys(v).sort().map(k => [k, sorted(v[k])])) : v;
  const canonical = v => JSON.stringify(sorted(v));
  // SHA256 is embedded below by the source generator, with Unicode parity tests.
  const sha256hex = (text) => {
  const rr = (v, a) => (v >>> a) | (v << (32 - a));
  const maxWord = Math.pow(2, 32);
  const bytes = encodeURIComponent(String(text)).replace(/%([0-9A-F]{2})/g, (_, h) => String.fromCharCode(parseInt(h, 16)));
  const bitLength = bytes.length * 8;
  let hash = [];
  const k = [];
  let primes = 0;
  const composite = {};
  for (let c = 2; primes < 64; c++) {
    if (!composite[c]) {
      for (let i = 0; i < 313; i += c) composite[i] = c;
      hash[primes] = (Math.pow(c, 0.5) * maxWord) | 0;
      k[primes++] = (Math.pow(c, 1 / 3) * maxWord) | 0;
    }
  }
  let s = bytes + '\x80';
  while (s.length % 64 - 56) s += '\x00';
  const words = [];
  for (let i = 0; i < s.length; i++) words[i >> 2] |= s.charCodeAt(i) << ((3 - i) % 4) * 8;
  words[words.length] = (bitLength / maxWord) | 0;
  words[words.length] = bitLength;
  for (let j = 0; j < words.length;) {
    const w = words.slice(j, j += 16);
    const old = hash;
    hash = hash.slice(0, 8);
    for (let i = 0; i < 64; i++) {
      const w15 = w[i - 15];
      const w2 = w[i - 2];
      const a = hash[0];
      const e = hash[4];
      const t1 = hash[7] + (rr(e, 6) ^ rr(e, 11) ^ rr(e, 25)) + ((e & hash[5]) ^ (~e & hash[6])) + k[i] + (w[i] = (i < 16) ? w[i] : (w[i - 16] + (rr(w15, 7) ^ rr(w15, 18) ^ (w15 >>> 3)) + w[i - 7] + (rr(w2, 17) ^ rr(w2, 19) ^ (w2 >>> 10))) | 0);
      const t2 = (rr(a, 2) ^ rr(a, 13) ^ rr(a, 22)) + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
      hash = [(t1 + t2) | 0].concat(hash);
      hash[4] = (hash[4] + t1) | 0;
    }
    for (let i = 0; i < 8; i++) hash[i] = (hash[i] + old[i]) | 0;
  }
  let out = '';
  for (let i = 0; i < 8; i++) for (let j = 3; j + 1; j--) { const b = (hash[i] >> (j * 8)) & 255; out += (b < 16 ? '0' : '') + b.toString(16); }
  return out;
};

  const digest = value => sha256hex(JSON.stringify(value));
  const caseLabel = b => 'dubakwi-' + digest([b.scope, b.owner_id, b.first_request_id]).slice(0, 40);
  const eventId = s => digest([s.scope, s.case_id, s.request_id, s.phase]);
  function jiraText(value) {
    if (typeof value === 'string') return value;
    if (!object(value)) return fail('context_invalid');
    if (value.type === 'text') return typeof value.text === 'string' ? value.text : fail('context_invalid');
    if (value.type === 'hardBreak') return '\n';
    if (!['doc', 'paragraph', 'codeBlock', 'bulletList', 'orderedList', 'listItem'].includes(value.type)
        || !Array.isArray(value.content ?? [])) return fail('context_invalid');
    return (value.content ?? []).map(jiraText).join(['doc', 'bulletList', 'orderedList', 'listItem'].includes(value.type) ? '\n' : '');
  }
  function validateFacts(f) {
    if (!object(f) || typeof f.summary !== 'string') return fail('context_invalid');
    for (const k of ['reported', 'confirmed']) {
      if (!Array.isArray(f[k])) return fail('context_invalid');
      for (const x of f[k]) {
        if (!object(x) || !text(x.key) || typeof x.value !== 'string'
            || !['user', 'document', 'api'].includes(x.origin)
            || ('reference' in x && typeof x.reference !== 'string')
            || (k === 'confirmed' && x.origin === 'user')) return fail('context_invalid');
      }
    }
    for (const k of ['attempted_actions', 'missing', 'uncertainties']) {
      if (!Array.isArray(f[k]) || !f[k].every(x => typeof x === 'string')) return fail('context_invalid');
    }
    if (!Array.isArray(f.evidence_refs) || !f.evidence_refs.every(x => object(x) && text(x.doc)
        && text(x.section) && typeof x.score === 'number' && Number.isFinite(x.score)
        )) return fail('context_invalid');
    if (/\b0\d{1,2}[-. ]?\d{3,4}[-. ]?\d{4}\b|[\w.+-]+@[\w-]+\.[\w.-]+/.test(JSON.stringify(f))) return fail('context_unmasked');
  }
  function validateSnapshot(s, b) {
    if (!object(s) || s.schema_version !== 1) return fail('context_invalid');
    for (const k of ['scope', 'case_id', 'owner_id', 'first_request_id', 'ticket_key']) {
      if (!text(b[k]) || s[k] !== b[k]) return fail('context_not_linked');
    }
    if (!Number.isInteger(s.revision) || s.revision < 1 || !text(s.request_id) || s.request_id.length > 64
        || !['wait', 'handoff', 'close', 'followup', 'save'].includes(s.phase) || s.event_id !== eventId(s)) return fail('context_invalid');
    const p = s.support;
    if (!object(p) || p.version !== null) return fail('context_invalid');
    for (const k of ['case_id', 'owner_id', 'first_request_id']) if (p[k] !== b[k]) return fail('context_not_linked');
    if (p.ticket_id !== b.ticket_key || !Number.isInteger(p.attempt) || p.attempt < 1
        || !['received', 'waiting_info', 'handed_off', 'closed_guidance', 'closed_rejected'].includes(p.status)
        || ![null, 'support', 'security'].includes(p.assignee_role ?? null)
        || ![null, 'normal', 'high'].includes(p.priority ?? null)
        || (p.status === 'handed_off' && (!p.assignee_role || !p.priority))) return fail('context_invalid');
    validateFacts(s.facts);
    if (encodeURIComponent(JSON.stringify(s)).replace(/%[A-F0-9]{2}|./g, 'x').length > 16000) return fail('context_too_large');
    return s;
  }
  function validateIssue(issue, b) {
    const f = issue?.fields ?? {};
    const lines = jiraText(f.description ?? '').split(/\r?\n/);
    if (!/^JBYS-[0-9]+$/.test(issue?.key ?? '') || issue.key !== b.ticket_key
        || !Array.isArray(f.labels) || !f.labels.includes(caseLabel(b))
        || !lines.includes('case_id: ' + b.case_id)
        || !lines.includes('first_request_id: ' + b.first_request_id)) return fail('context_not_linked');
  }
  function selectSnapshot(comments, b, authors, requestId = null) {
    if (!Array.isArray(authors) || !authors.length) return fail('context_author_unconfigured');
    const events = new Map(), revisions = new Map(), candidates = [];
    for (const c of comments) {
      const body = jiraText(c.body ?? '');
      if (!body.startsWith(MARKER + '\n')) continue;
      if (!authors.includes(c.author?.accountId)) return fail('context_author_denied');
      let s;
      try { s = JSON.parse(body.slice(MARKER.length + 1)); } catch { return fail('context_invalid'); }
      validateSnapshot(s, b);
      const value = canonical(s);
      for (const [key, map] of [[s.event_id, events], [s.revision, revisions]]) {
        if (map.has(key) && map.get(key) !== value) return fail('context_conflict');
        map.set(key, value);
      }
      if (requestId === null || s.request_id === requestId) candidates.push(s);
    }
    if (!candidates.length) return fail('context_missing');
    return candidates.reduce((a, b) => a.revision >= b.revision ? a : b);
  }
  function buildSnapshot(b, requestId, phase, revision, support, facts) {
    const s = {schema_version: 1, ...b, request_id: requestId, phase, revision, support, facts};
    s.event_id = eventId(s);
    return validateSnapshot(s, b);
  }
  function readPages(pages) {
    const comments = [];
    let expected = 0, total = null;
    for (const page of pages) {
      if (!object(page) || !Number.isInteger(page.total) || !Number.isInteger(page.startAt)
          || !Array.isArray(page.comments) || page.startAt !== expected
          || (total !== null && total !== page.total) || page.total < 0) return fail('context_incomplete');
      total = page.total;
      comments.push(...page.comments);
      expected += page.comments.length;
    }
    if (total === null || expected !== total) return fail('context_incomplete');
    return comments;
  }
  return {MARKER, canonical, digest, caseLabel, eventId, jiraText, validateFacts,
    validateSnapshot, validateIssue, selectSnapshot, buildSnapshot, readPages};
}

const CC = caseContextLibrary();
// END shared case-context library

const authors = (() => { try { return JSON.parse('__JIRA_CONTEXT_AUTHORS_JSON__'); } catch { return []; } })();
const remaining = deadline => Date.parse(deadline) - Date.now();
const bindingFor = (r, key) => ({scope:r.state_ref.scope, owner_id:r.state_ref.owner_id,
  case_id:r.case_id, first_request_id:r.first_request_id, ticket_key:key});
const pages = () => CC.readPages($input.all().map(x => {
  if (x.json.statusCode !== 200) throw new Error('context_read_failed');
  return x.json.body;
}));
const select = (comments,b,requestId=null) => CC.selectSnapshot(comments,b,authors,requestId);
const mask = v => typeof v === 'string' ? v.replace(/\b0\d{1,2}[-. ]?\d{3,4}[-. ]?\d{4}\b/g,'***-****-****').replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g,'***@***')
  : Array.isArray(v) ? v.map(mask) : v && typeof v === 'object' ? Object.fromEntries(Object.entries(v).map(([k,x])=>[k,mask(x)])) : v;
const commentPath = key => '/rest/api/2/issue/'+encodeURIComponent(key)+'/comment';

const input=$('S01 상태 명령 수신').first().json,p=$('S23 최종 문맥 댓글 조회 준비').first().json;

const fail = reason => [{json:{request_id:input.state_ref.request_id,ok:false,state_ref:input.state_ref,error_code:'state_error',
recovery:{version:1,mode:'jira_ref',action:'finish',args:null,reference:{jira_issue_key:input.ticket_id,case_id:input.case_id,owner_id:input.state_ref.owner_id},reason}}}];
const finish = () => [{json:{route:'finish',finish_payload:{op:'finish',state_ref:input.state_ref,args:{response:input.response,current_step:'respond'}}}}];

try {
 if(input.expected_case_version!==null||remaining(input.deadline_at)<500||p.issue.statusCode!==200)return fail('context_read_failed');
 const b=bindingFor(input,input.ticket_id);CC.validateIssue(p.issue.body,b);
 const comments=pages(),latest=select(comments,b),actual=select(comments,b,input.state_ref.request_id);
 const status=input.outcome.support_status;
 const support={...actual.support,attempt:input.attempt,status,version:null};
 const category=p.issue.body.fields.status?.statusCategory?.key;
 if((status.startsWith('closed_')&&category!=='done')||(!status.startsWith('closed_')&&!['new','indeterminate'].includes(category)))return fail('context_status_conflict');
 if(status==='handed_off'){
   const labels=p.issue.body.fields.labels??[];
   let mapping={};try{mapping=JSON.parse('__ASSIGNEE_MAP_JSON__');}catch{}
   const expected=mapping[actual.support.assignee_role];
   if(!expected||!labels.includes('dubakwi-alert-sent-'+actual.support.assignee_role)||p.issue.body.fields.assignee?.accountId!==expected)return fail('context_effect_unverified');
 }
 if(CC.canonical(actual.support)===CC.canonical(support)&&CC.canonical(actual.facts)===CC.canonical(mask(input.facts)))return finish();
 if(remaining(input.deadline_at)<4000)return fail('deadline_exceeded');
 const snapshot=CC.buildSnapshot(b,input.state_ref.request_id,'save',latest.revision+1,support,mask(input.facts));
 const existing=comments.map(c=>CC.jiraText(c.body??'')).filter(t=>t.startsWith(CC.MARKER+'\n')).map(t=>JSON.parse(t.slice(CC.MARKER.length+1))).find(s=>s.event_id===snapshot.event_id);
 if(existing)return fail('context_conflict');
 return [{json:{route:'amend',snapshot,deadline_at:input.deadline_at,req:{path:commentPath(input.ticket_id),body:{body:CC.MARKER+'\n'+JSON.stringify(snapshot)}}}}];
}catch(e){return fail(e.message);}

const input = $('S01 상태 명령 수신').item.json;
const rid = input.request && input.request.request_id ? input.request.request_id : null;
const result = (mode, http, code, response) => ({request_id:rid, mode, state_ref:null, support:null, facts:null, response, http_status:http, error_code:code});
const reject = (mode, http, code, message) => result(mode, http, code, {error:message, codes:[code]});
let raw = $json.result;
if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch { raw = null; } }
if (!raw || raw.ok !== true) return [{json:result('error', 503, 'state_error', null)}];
if (raw.found !== true) return [{json:reject('conflict', 400, 'invalid_case_ref', '알 수 없는 문의 번호입니다.')}];
if (raw.owner_match !== true) return [{json:reject('conflict', 403, 'case_access_denied', '이 문의에 접근할 수 없습니다.')}];
